package com.vocast.app;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

/** Content-addressed chapter files and one atomically replaced manifest. */
final class SnapshotStore {
 private final File dir,manifest;private JSONObject current;
 SnapshotStore(File root){dir=new File(root,"chapters");dir.mkdirs();manifest=new File(root,"library.json");}
 private JSONObject manifest()throws Exception{if(current==null&&manifest.isFile())current=new JSONObject(new String(AudioFiles.read(manifest,16*1024*1024),StandardCharsets.UTF_8));return current;}
 synchronized JSONObject loadHeader()throws Exception{JSONObject raw=manifest();if(raw==null)return null;JSONObject header=new JSONObject(raw.toString());JSONArray books=header.getJSONArray("books");for(int i=0;i<books.length();i++){JSONArray chapters=books.getJSONObject(i).getJSONArray("chapters");for(int j=0;j<chapters.length();j++){JSONObject c=chapters.getJSONObject(j);if(!c.has("title")){JSONObject full=loadChapter(c.getString("id"));for(String key:new String[]{"title","status","audio","duration","summary"})if(full.has(key))c.put(key,full.get(key));c.put("textLength",full.optString("text").length()).put("segmentCount",full.optJSONArray("segments")==null?0:full.getJSONArray("segments").length());}c.remove("storageRef");c.put("unloaded",true).put("segments",new JSONArray());}}return header;}
 synchronized JSONObject loadChapter(String id)throws Exception{String hash=refs(manifest()).get(id);if(hash==null||!hash.matches("[a-f0-9]{64}"))throw new IOException("章节索引损坏");JSONObject full=new JSONObject(new String(AudioFiles.read(new File(dir,hash+".json"),16*1024*1024),StandardCharsets.UTF_8));if(!full.getString("id").equals(id))throw new IOException("章节索引不匹配");return full;}
 private static Map<String,String> refs(JSONObject state)throws Exception{Map<String,String> out=new HashMap<>();if(state==null)return out;JSONArray books=state.getJSONArray("books");for(int i=0;i<books.length();i++){JSONArray chapters=books.getJSONObject(i).getJSONArray("chapters");for(int j=0;j<chapters.length();j++){JSONObject c=chapters.getJSONObject(j);if(c.has("storageRef"))out.put(c.getString("id"),c.getString("storageRef"));}}return out;}
 synchronized JSONObject load()throws Exception{JSONObject raw=manifest();if(raw==null)return null;JSONObject state=new JSONObject(raw.toString());JSONArray books=state.getJSONArray("books");Set<String> keep=new HashSet<>(refs(raw).values());for(int i=0;i<books.length();i++){JSONArray chapters=books.getJSONObject(i).getJSONArray("chapters");for(int j=0;j<chapters.length();j++){JSONObject ref=chapters.getJSONObject(j);String hash=ref.getString("storageRef");if(!hash.matches("[a-f0-9]{64}"))throw new IOException("章节索引损坏");JSONObject full=new JSONObject(new String(AudioFiles.read(new File(dir,hash+".json"),16*1024*1024),StandardCharsets.UTF_8));if(!full.getString("id").equals(ref.getString("id")))throw new IOException("章节索引不匹配");chapters.put(j,full);}}File[] files=dir.listFiles();if(files!=null)for(File f:files)if(f.getName().matches("[a-f0-9]{64}\\.json")&&!keep.contains(f.getName().substring(0,64)))f.delete();return state;}
 synchronized void save(String header,String changes)throws Exception{JSONObject next=new JSONObject(header);Map<String,String> old=refs(manifest()),all=new HashMap<>(old);JSONArray changed=new JSONArray(changes);for(int i=0;i<changed.length();i++){JSONObject c=changed.getJSONObject(i);byte[] data=c.toString().getBytes(StandardCharsets.UTF_8);StringBuilder hash=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(data))hash.append(String.format(Locale.ROOT,"%02x",b));File target=new File(dir,hash+".json");if(!target.exists())atomic(target,data);all.put(c.getString("id"),hash.toString());}JSONArray books=next.getJSONArray("books");Set<String> keep=new HashSet<>();for(int i=0;i<books.length();i++){JSONArray chapters=books.getJSONObject(i).getJSONArray("chapters");for(int j=0;j<chapters.length();j++){JSONObject c=chapters.getJSONObject(j);String hash=all.get(c.getString("id"));if(hash==null)throw new IOException("章节尚未保存");c.put("storageRef",hash);keep.add(hash);}}atomic(manifest,next.toString().getBytes(StandardCharsets.UTF_8));current=next;for(String hash:old.values())if(!keep.contains(hash))new File(dir,hash+".json").delete();}
 private static void atomic(File target,byte[] data)throws Exception{File tmp=File.createTempFile("snapshot-",".tmp",target.getParentFile());try{try(FileOutputStream out=new FileOutputStream(tmp)){out.write(data);out.getFD().sync();}Files.move(tmp.toPath(),target.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{if(tmp.exists())tmp.delete();}}
}
